import { formatPrice } from './utils'

test('formats cents', () => {
  expect(formatPrice(1999)).toBe('$19.99')
})

test('formats zero', () => {
  expect(formatPrice(0)).toBe('$0.00')
})

test('rounds', () => {
  expect(formatPrice(5)).toBe('$0.05')
})

test('NaN logs and returns $0.00', () => {
  expect(formatPrice(NaN)).toBe('$0.00')
})
